import{I as p,o as t,c as o,b6 as n,J as r,w as h,j as s,a as l}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"用 Jobs to Be Done 找到使用者真正想完成的事","description":"面向零基礎讀者的 Jobs to Be Done 入門文章。理解使用者不是在買功能，而是在特定場景裡“僱用”你的產品完成進展，並學會用 JTBD 拆解產品方向、訪談問題與 AI 提示詞。","frontmatter":{"title":"用 Jobs to Be Done 找到使用者真正想完成的事","description":"面向零基礎讀者的 Jobs to Be Done 入門文章。理解使用者不是在買功能，而是在特定場景裡“僱用”你的產品完成進展，並學會用 JTBD 拆解產品方向、訪談問題與 AI 提示詞。"},"headers":[],"relativePath":"zh-tw/stage-1/appendix-jobs-to-be-done/index.md","filePath":"zh-tw/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"zh-tw/stage-1/appendix-jobs-to-be-done/index.md"},_=Object.assign(d,{setup(c){const i="約 <strong>1.5 小時</strong>";return(b,a)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[a[1]||(a[1]=n('<h1 id="用-jobs-to-be-done-找到使用者真正想完成的事" tabindex="-1">用 Jobs to Be Done 找到使用者真正想完成的事 <a class="header-anchor" href="#用-jobs-to-be-done-找到使用者真正想完成的事" aria-label="Permalink to “用 Jobs to Be Done 找到使用者真正想完成的事”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="本章導讀" tabindex="-1">本章導讀 <a class="header-anchor" href="#本章導讀" aria-label="Permalink to “本章導讀”">​</a></h2>',3)),r(e,{duration:i,tags:["JTBD","使用者需求","產品思維","需求洞察"],coreOutput:"1 條更像真實需求的 JTBD 句子",expectedOutput:"能把模糊點子收成一個更具體的使用者場景和 MVP 方向"},{default:h(()=>[...a[0]||(a[0]=[s("p",null,"很多人剛開始做產品時，最容易犯的一個錯誤是把注意力全部放在“我要做什麼功能”上。看別人有智慧分類，你也想加；看別人有自動總結，你也想接；看別人做了 Agent、多模態、工作流，你也覺得自己不能少。",-1),s("p",null,"但現實裡，使用者很少是因為“這個功能名字很酷”才決定用一個產品。他們更多是在某個具體時刻，想把一件事情推進下去，於是臨時“僱用”了一個工具、一個服務，甚至一個人，來幫自己完成這一步。",-1),s("p",null,[l("這正是 "),s("strong",null,"Jobs to Be Done（JTBD）"),l(" 這套方法想提醒我們的事情："),s("strong",null,"使用者不是在購買功能本身，而是在僱用某種解決方案，幫助自己完成一個進展。")],-1),s("p",null,"本篇文章會用盡量直白的語言，帶你從零理解 JTBD，並把它變成你做 AI 應用時能直接拿來用的分析工具。",-1)])]),_:1}),a[2]||(a[2]=n(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：看完後，你會更清楚怎樣把一個模糊點子，收成一句真正有使用者場景的需求，而不是腦子裡只有一堆功能名。</p><p><strong>行動項</strong>：寫 1 句模糊點子，找 3 個潛在使用者聊“最近一次怎麼處理”，再整理成 1 條 JTBD 句子。</p><p><strong>結果</strong>：你會得到一個更清楚的需求假設，知道第一版該先解決什麼。</p><p><strong>關鍵詞跳轉</strong>：<a href="#jtbd-what">JTBD 是什麼</a> · <a href="#jtbd-formula">一句話公式</a> · <a href="#jtbd-ai">AI 怎麼幫你</a></p></div><h2 id="你將學到以下內容" tabindex="-1">你將學到以下內容 <a class="header-anchor" href="#你將學到以下內容" aria-label="Permalink to “你將學到以下內容”">​</a></h2><ol><li>什麼是 Jobs to Be Done，為什麼它比“功能腦暴”更接近真實需求</li><li>如何區分“使用者說想要的功能”和“使用者真正想完成的事”</li><li>怎樣用一套簡單模板，把一個模糊點子拆成場景、觸發、障礙和成功標準</li><li>如何把 JTBD 用在 AI 產品、訪談提問和提示詞整理裡</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-什麼是-jobs-to-be-done" tabindex="-1"><a href="#top-jtbd">1. 什麼是 Jobs to Be Done</a> <a class="header-anchor" href="#_1-什麼是-jobs-to-be-done" aria-label="Permalink to “1. 什麼是 Jobs to Be Done”">​</a></h2><p>Jobs to Be Done 常被簡稱為 <strong>JTBD</strong>。它背後的核心想法，和 Clayton Christensen 團隊推廣的那句經典表達有關：<strong>使用者會“僱用”某個產品來完成一件事。</strong></p><p>這裡的“事”，不是待辦清單裡那種表面動作，而是使用者希望自己狀態發生的一種 <strong>進展</strong> 。比如：</p><ul><li>不是“我要一個 AI 紀要工具”，而是“我想在會後 10 分鐘內把重點、待辦和責任人整理清楚，別再靠回憶補筆記”</li><li>不是“我要一個記賬 App”，而是“我想知道錢到底花去哪了，好讓我月底別再焦慮”</li><li>不是“我要一個簡歷最佳化器”，而是“我想更有把握地投出一份像樣的簡歷，不想每次投遞都懷疑自己寫得太差”</li></ul><p>所以，<strong>JTBD 關注的不是產品長什麼樣，而是使用者為什麼在這個時刻需要它。</strong></p><p>這也是為什麼很多看似不同的產品，實際上在競爭同一個 job。使用者想“在上班路上不那麼無聊”，可僱用的物件可能是短影片、播客、遊戲、聊天，甚至打瞌睡。使用者想“快速搞懂一份很長的 PDF”，可僱用的物件可能是 AI 摘要工具、實習生、同事、自己硬著頭皮看，或者乾脆先不看。</p><p>一旦你用這種視角看問題，你會發現自己真正的競爭對手，往往並不只是“另一個長得像你的 App”，而是 <strong>使用者當前所有可接受的替代方案</strong> 。</p><h2 id="_2-jtbd-和使用者畫像、功能列表有什麼不同" tabindex="-1">2. JTBD 和使用者畫像、功能列表有什麼不同 <a class="header-anchor" href="#_2-jtbd-和使用者畫像、功能列表有什麼不同" aria-label="Permalink to “2. JTBD 和使用者畫像、功能列表有什麼不同”">​</a></h2><p>很多新手剛開始做需求分析時，會先寫使用者畫像：25 歲，女生，一線城市，白領，喜歡效率工具，願意嘗試新產品。這樣的資訊不能說完全沒用，但它通常 <strong>不夠解釋一個人為什麼會在此刻採取行動。</strong></p><p>JTBD 更關心的是下面這些問題：</p><ul><li>他是在什麼場景下決定找解決方案的</li><li>當時到底卡住了什麼</li><li>他想把什麼事情推進到下一步</li><li>現在正在用什麼笨辦法撐著</li><li>如果事情解決得好，什麼結果會讓他覺得“值了”</li></ul><p>也就是說，<strong>使用者畫像更像“這個人大概是誰”，JTBD 更像“這個人現在到底想完成什麼”。</strong></p><p>同樣地，功能列表也容易把人帶偏。使用者說“我想要匯出 Word”“我想要 AI 改寫”“我想要語音輸入”，這些都只是表層表達。JTBD 會繼續往下追問：</p><ul><li>為什麼你現在需要匯出 Word，而不是 PDF？</li><li>你想改寫，是因為文風太差，還是因為需要適配不同物件？</li><li>你想語音輸入，是因為懶得打字，還是因為你經常在走路、開車、開會後馬上記錄？</li></ul><p>很多時候，<strong>功能只是 job 的一種臨時翻譯</strong> 。如果你只收集功能，很容易把產品做成“使用者說什麼就堆什麼”；如果你能看見背後的 job，才更有機會做出真正順手、真正有競爭力的方案。</p><h2 id="_3-一個零基礎也能理解的例子" tabindex="-1">3. 一個零基礎也能理解的例子 <a class="header-anchor" href="#_3-一個零基礎也能理解的例子" aria-label="Permalink to “3. 一個零基礎也能理解的例子”">​</a></h2><p>先不要急著想複雜的 AI 產品，我們從一個生活例子開始。</p><p>假設有人早上出門前總來不及喫早餐，於是經常在地鐵口買一個三明治和咖啡。表面上看，他“購買”的是早餐；但如果用 JTBD 看，他真正想完成的事可能是：</p><ul><li>在趕時間的早晨，用最省腦力的方式解決一頓飯</li><li>讓自己在到公司前不至於餓得發慌</li><li>不因為喫早餐耽誤通勤節奏</li></ul><p>這時候，使用者僱用的不是“某個固定品牌的三明治”，而是一個能幫他把早晨順利推進下去的解決方案。如果隔壁便利店更快、更近、更穩定，他可能立刻換掉原來的選擇。</p><p>把這個邏輯搬到 AI 產品裡就更明顯了。</p><p>比如你想做一個“AI 會議紀要工具”。如果只停在功能層面，你會很容易開始想：</p><ul><li>要不要支援上傳音訊</li><li>要不要接入說話人分離</li><li>要不要匯出 Markdown</li><li>要不要自動生成待辦</li></ul><p>這些都沒錯，但還不夠。用 JTBD 再問一層，使用者真正想完成的可能是：</p><ul><li>我想在會後 10 分鐘內，把討論結果同步給沒參會的人</li><li>我想把待辦、責任人和截止時間提幹淨，別讓團隊靠記憶協作</li><li>我想減少重複整理會議內容的時間，把精力留給決策和推進</li></ul><p>一旦 job 被說清楚，很多功能優先順序就會自動浮出來。第一版最重要的也許不是“支援 12 種匯出格式”，而是：</p><ul><li>紀要結構要足夠清楚</li><li>待辦提取要穩定</li><li>分享連結要方便</li><li>輸出結果要讓人敢直接轉發給團隊</li></ul><p>這就是 JTBD 的價值：<strong>它能幫助你從“我要堆哪些能力”回到“我要幫使用者推進什麼進展”。</strong></p><h2 id="_4-一個好用的-jtbd-模板" tabindex="-1">4. 一個好用的 JTBD 模板 <a class="header-anchor" href="#_4-一個好用的-jtbd-模板" aria-label="Permalink to “4. 一個好用的 JTBD 模板”">​</a></h2><p>如果你是零基礎，可以先不要試圖把 JTBD 想得很學術。先抓住最實用的 5 個要素就夠了。</p><h3 id="_4-1-場景" tabindex="-1">4.1 場景 <a class="header-anchor" href="#_4-1-場景" aria-label="Permalink to “4.1 場景”">​</a></h3><p>使用者是在什麼時刻、什麼環境裡想起這個產品的？</p><ul><li>是開完會以後</li><li>是老闆臨時要材料的時候</li><li>是晚上準備投簡歷的時候</li><li>是月底發現錢又不夠花的時候</li></ul><p><strong>沒有場景的需求，通常都還不夠真實。</strong></p><h3 id="_4-2-觸發" tabindex="-1">4.2 觸發 <a class="header-anchor" href="#_4-2-觸發" aria-label="Permalink to “4.2 觸發”">​</a></h3><p>是什麼讓他決定立刻找解決方案？</p><ul><li>被長文件壓住，不知道從哪開始看</li><li>明天要交材料，今天才發現格式亂七八糟</li><li>剛被領導追問進度，意識到自己沒有整理清楚</li><li>想堅持記錄，但手寫、複製、整理都太麻煩</li></ul><p>觸發點往往帶著情緒。這個情緒很重要，因為它決定了使用者為什麼會在這一刻產生行動。</p><h3 id="_4-3-想完成的進展" tabindex="-1">4.3 想完成的進展 <a class="header-anchor" href="#_4-3-想完成的進展" aria-label="Permalink to “4.3 想完成的進展”">​</a></h3><p>他不只是想“做個動作”，而是想把自己推進到什麼新狀態？</p><ul><li>從混亂到清楚</li><li>從焦慮到安心</li><li>從拖延到啟動</li><li>從低效到順手</li><li>從說不明白到能直接交付</li></ul><p>這一步裡，“進展”這個詞非常關鍵。因為很多人真正買的不是工具，而是 <strong>狀態變化</strong> 。</p><h3 id="_4-4-當前替代方案" tabindex="-1">4.4 當前替代方案 <a class="header-anchor" href="#_4-4-當前替代方案" aria-label="Permalink to “4.4 當前替代方案”">​</a></h3><p>現在沒有你的產品時，他怎麼做？</p><ul><li>手工複製貼上</li><li>用 Excel 或備忘錄硬撐</li><li>找同事幫忙</li><li>拖著不做</li><li>在幾個工具之間來回切</li></ul><p>誰是替代方案，誰就是你的真實競爭環境。</p><h3 id="_4-5-成功標準" tabindex="-1">4.5 成功標準 <a class="header-anchor" href="#_4-5-成功標準" aria-label="Permalink to “4.5 成功標準”">​</a></h3><p>事情怎樣纔算真的被解決？</p><ul><li>10 分鐘內得到可分享的結果</li><li>不需要二次大改就能發給別人</li><li>不容易漏項、出錯、忘事</li><li>第一次用就知道下一步怎麼走</li></ul><p>如果你連“使用者怎麼判斷值不值”都說不清，那這個方向大機率還沒有收斂好。</p><p><a id="jtbd-formula"></a></p><h2 id="_5-直接套用的一句話公式" tabindex="-1"><a href="#top-jtbd">5. 直接套用的一句話公式</a> <a class="header-anchor" href="#_5-直接套用的一句話公式" aria-label="Permalink to “5. 直接套用的一句話公式”">​</a></h2><p>當你想梳理一個產品方向時，可以先套這個非常實用的句式：</p><blockquote><p>當 __________ 的時候，我想要 __________，以便於 __________。<br> 現在我只能透過 __________ 來勉強完成這件事。</p></blockquote><p>比如：</p><blockquote><p>當我開完一場資訊量很大的專案會時，我想要快速得到一份帶待辦、責任人和截止時間的紀要，以便於我能馬上同步團隊並推進執行。<br> 現在我只能靠自己回憶、翻聊天記錄和手工整理來勉強完成這件事。</p></blockquote><p>再比如：</p><blockquote><p>當我準備投遞一個新崗位時，我想要快速把已有經歷改寫成更貼合崗位的版本，以便於我能更有把握地投出一份像樣的簡歷。<br> 現在我只能反覆複製舊簡歷、手改措辭，改到最後越來越不確定。</p></blockquote><p>如果你能把一句話寫到這種清晰程度，後面的頁面設計、提示詞設計、功能優先順序判斷，都會容易很多。</p><h2 id="_6-做-ai-產品時-特別要看的三層-job" tabindex="-1">6. 做 AI 產品時，特別要看的三層 job <a class="header-anchor" href="#_6-做-ai-產品時-特別要看的三層-job" aria-label="Permalink to “6. 做 AI 產品時，特別要看的三層 job”">​</a></h2><p>很多 AI 產品在功能演示時看上去很強，但真正上線之後卻留不住人，常見原因是隻解決了表層動作，沒有解決更深的 job。</p><p>你可以把一個 job 粗略分成三層來看：</p><h3 id="_6-1-功能層" tabindex="-1">6.1 功能層 <a class="header-anchor" href="#_6-1-功能層" aria-label="Permalink to “6.1 功能層”">​</a></h3><p>最表面的任務是什麼？</p><ul><li>總結文件</li><li>改寫文案</li><li>提取待辦</li><li>生成圖片</li></ul><p>這是使用者嘴上最容易說出來的一層。</p><h3 id="_6-2-情緒層" tabindex="-1">6.2 情緒層 <a class="header-anchor" href="#_6-2-情緒層" aria-label="Permalink to “6.2 情緒層”">​</a></h3><p>使用者希望減少什麼不舒服，或者獲得什麼感受？</p><ul><li>不想那麼慌</li><li>不想顯得不專業</li><li>不想每次都從零開始</li><li>想更有掌控感</li></ul><p>很多付費意願，實際上和情緒層關係很大。</p><h3 id="_6-3-社會層" tabindex="-1">6.3 社會層 <a class="header-anchor" href="#_6-3-社會層" aria-label="Permalink to “6.3 社會層”">​</a></h3><p>使用者希望在別人眼裡變成什麼樣？</p><ul><li>看起來更靠譜</li><li>在團隊裡更有組織能力</li><li>在客戶面前更專業</li><li>在社交平臺上更會表達</li></ul><p>如果你只做功能層，產品很容易被替代；如果你同時理解了情緒層和社會層，你就更容易找到真正有黏性的價值。</p><h2 id="_7-用-jtbd-反過來篩產品方向" tabindex="-1">7. 用 JTBD 反過來篩產品方向 <a class="header-anchor" href="#_7-用-jtbd-反過來篩產品方向" aria-label="Permalink to “7. 用 JTBD 反過來篩產品方向”">​</a></h2><p>有時候不是你已經有產品，而是你手裡有 3 到 5 個點子，不知道做哪個。這時 JTBD 很適合拿來做篩選。</p><p>你可以拿著每個點子，分別問自己 5 個問題：</p><ol><li>這個點子對應的場景是不是足夠具體？</li><li>使用者現在是否已經在用某種笨辦法解決？</li><li>這個 job 的痛感是否足夠強，或者足夠高頻？</li><li>如果我做好了，使用者會不會明顯感受到“狀態變好了”？</li><li>第一版能不能只圍繞這個 job 的關鍵一步，做出一個很小但有用的版本？</li></ol><p>如果一個方向講到最後還是隻能說“感覺挺有意思”，卻說不清觸發、替代方案和成功標準，那它大機率還只是一個模糊靈感，不是一個成熟方向。</p><h2 id="_8-可以直接拿去訪談使用者的問題" tabindex="-1">8. 可以直接拿去訪談使用者的問題 <a class="header-anchor" href="#_8-可以直接拿去訪談使用者的問題" aria-label="Permalink to “8. 可以直接拿去訪談使用者的問題”">​</a></h2><p>很多人一做調研就問：“你想要什麼功能？”這種問法很容易得到表面答案。</p><p>JTBD 更適合問下面這些問題：</p><ul><li>最近一次你遇到這個問題是什麼時候？</li><li>當時你在做什麼，為什麼會卡住？</li><li>你最後是怎麼解決的？</li><li>這個過程裡最煩、最慢、最不放心的地方是什麼？</li><li>如果有一個工具能幫你，什麼結果會讓你覺得真的有用？</li><li>你試過哪些替代方法？為什麼它們不夠好？</li></ul><p>這種問法有個好處：它會把對話拉回真實經歷，而不是停留在想象中的偏好。</p><h2 id="_9-用-ai-幫你做-jtbd-拆解" tabindex="-1">9. 用 AI 幫你做 JTBD 拆解 <a class="header-anchor" href="#_9-用-ai-幫你做-jtbd-拆解" aria-label="Permalink to “9. 用 AI 幫你做 JTBD 拆解”">​</a></h2><p>JTBD 本身不是 AI 發明的，但 AI 很適合幫你整理和提煉 JTBD。</p><p>比如你已經收集了 5 到 10 條使用者反饋，就可以把它們丟給模型，讓它按以下結構總結：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請你扮演產品研究助手。</span></span>
<span class="line"><span>我會給你一些使用者原話，請你不要先給功能建議，</span></span>
<span class="line"><span>而是先按 Jobs to Be Done 的框架整理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 使用者處在什麼場景</span></span>
<span class="line"><span>2. 觸發他採取行動的事件是什麼</span></span>
<span class="line"><span>3. 他真正想完成的進展是什麼</span></span>
<span class="line"><span>4. 當前替代方案是什麼</span></span>
<span class="line"><span>5. 他最在意的成功標準是什麼</span></span>
<span class="line"><span>6. 這些反饋裡反覆出現的情緒詞有哪些</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最後，請把這些內容整理成 3 個最值得優先驗證的 JTBD 假設。</span></span></code></pre></div><p>如果你已經有一個點子，也可以讓 AI 幫你做第一輪收斂：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一個 [你的產品想法]。</span></span>
<span class="line"><span>請不要直接給我功能列表，而是用 Jobs to Be Done 方法幫我分析：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 這個產品可能服務哪些具體場景</span></span>
<span class="line"><span>2. 每個場景中使用者想完成的核心 job 是什麼</span></span>
<span class="line"><span>3. 現有替代方案有哪些</span></span>
<span class="line"><span>4. 哪個 job 最適合作為 MVP 的起點，為什麼</span></span>
<span class="line"><span>5. 請把最終推薦的 job 寫成一句清晰的 JTBD 句子</span></span></code></pre></div><p>這樣做的好處是，你不會一上來就被 AI 帶去“腦暴 50 個功能”，而是先把方向講清楚。</p><h2 id="_10-新手最常見的-4-個誤區" tabindex="-1">10. 新手最常見的 4 個誤區 <a class="header-anchor" href="#_10-新手最常見的-4-個誤區" aria-label="Permalink to “10. 新手最常見的 4 個誤區”">​</a></h2><h3 id="_10-1-把-job-寫成功能名" tabindex="-1">10.1 把 job 寫成功能名 <a class="header-anchor" href="#_10-1-把-job-寫成功能名" aria-label="Permalink to “10.1 把 job 寫成功能名”">​</a></h3><p>“AI 總結”“智慧分類”“自動生成”都不是 job，它們只是可能的實現方式。</p><h3 id="_10-2-把人羣寫得很寬" tabindex="-1">10.2 把人羣寫得很寬 <a class="header-anchor" href="#_10-2-把人羣寫得很寬" aria-label="Permalink to “10.2 把人羣寫得很寬”">​</a></h3><p>“所有職場人”“所有學生”“所有創業者”通常都太泛。越泛，你越難看見真實場景。</p><h3 id="_10-3-只聽使用者說-不看使用者怎麼做" tabindex="-1">10.3 只聽使用者說，不看使用者怎麼做 <a class="header-anchor" href="#_10-3-只聽使用者說-不看使用者怎麼做" aria-label="Permalink to “10.3 只聽使用者說，不看使用者怎麼做”">​</a></h3><p>使用者會描述自己想要什麼，但他真正的優先順序，常常藏在他現在如何湊合解決問題裡。</p><h3 id="_10-4-一開始就想做完整平臺" tabindex="-1">10.4 一開始就想做完整平臺 <a class="header-anchor" href="#_10-4-一開始就想做完整平臺" aria-label="Permalink to “10.4 一開始就想做完整平臺”">​</a></h3><p>JTBD 的正確開啟方式，通常不是“我來做一個包打天下的大平臺”，而是先盯住一個場景裡最關鍵的一步，把它做到非常順手。</p><h2 id="_11-小結" tabindex="-1">11. 小結 <a class="header-anchor" href="#_11-小結" aria-label="Permalink to “11. 小結”">​</a></h2><p>Jobs to Be Done 最有價值的地方，不是給你一個新名詞，而是幫你換一個觀察角度：<strong>不要只盯著產品功能，而要盯著使用者想把什麼事情推進到下一步。</strong></p><p>當你開始反覆問自己：</p><ul><li>使用者是在什麼場景下僱用這個產品的</li><li>他到底卡在了哪裡</li><li>現在正用什麼辦法硬撐</li><li>事情解決後，狀態會發生什麼變化</li></ul><p>你會發現，很多原本模糊的點子一下子變清楚了，很多原本很花哨的功能也一下子沒那麼重要了。</p><p>做產品，尤其是做 AI 產品，最怕的是一開始就沉迷能力展示。JTBD 能幫你把注意力拉回到真正重要的地方：<strong>使用者為什麼需要你，以及你到底在幫他完成什麼進展。</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-如何利用-ai-幫你實踐-jtbd" tabindex="-1"><a href="#top-jtbd">12. 如何利用 AI 幫你實踐 JTBD</a> <a class="header-anchor" href="#_12-如何利用-ai-幫你實踐-jtbd" aria-label="Permalink to “12. 如何利用 AI 幫你實踐 JTBD”">​</a></h2><p>JTBD 不是 AI 發明的，但 AI 很適合在這套方法裡當你的研究助手、整理助手和對照助手。關鍵是：<strong>讓 AI 幫你整理和擴充套件，而不是替你臆測使用者。</strong></p><p>你可以這樣用：</p><h3 id="_12-1-讓-ai-幫你把模糊點子改寫成-jtbd-假設" tabindex="-1">12.1 讓 AI 幫你把模糊點子改寫成 JTBD 假設 <a class="header-anchor" href="#_12-1-讓-ai-幫你把模糊點子改寫成-jtbd-假設" aria-label="Permalink to “12.1 讓 AI 幫你把模糊點子改寫成 JTBD 假設”">​</a></h3><p>當你腦子裡只有一句模糊描述，比如“我想做一個幫大學生找實習的工具”，可以先讓 AI 幫你把它拆成幾種可能的 job：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我現在有一個模糊產品點子：[你的點子]</span></span>
<span class="line"><span>請不要直接給我功能列表，而是用 Jobs to Be Done 的方式幫我分析：</span></span>
<span class="line"><span>1. 可能對應哪些具體場景</span></span>
<span class="line"><span>2. 每個場景裡使用者真正想完成的進展是什麼</span></span>
<span class="line"><span>3. 當前替代方案可能是什麼</span></span>
<span class="line"><span>4. 哪個 job 最適合先做 MVP</span></span>
<span class="line"><span>請最後把每個 job 寫成一句清晰的 JTBD 句子。</span></span></code></pre></div><p>你甚至可以把輸入寫得很小白：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一個幫大學生找實習的東西。</span></span>
<span class="line"><span>我現在也說不清具體是做什麼，你幫我想想使用者到底想完成什麼事。</span></span></code></pre></div><p>AI 可能給出的有用輸出會像這樣：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>可能的 JTBD 方向：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 當我第一次準備投實習時，我想快速知道應該先準備哪些材料，</span></span>
<span class="line"><span>以便我不要因為資訊混亂一直拖著不投。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 當我看到一個實習崗位時，我想快速判斷自己是否值得投，</span></span>
<span class="line"><span>以便我不要在不合適的崗位上浪費太多時間。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 當我開始投遞時，我想把現有簡歷改成更貼合崗位的版本，</span></span>
<span class="line"><span>以便我能更快完成投遞並提高透過率。</span></span></code></pre></div><p>這種輸出的價值在於，它會把你原本一句很泛的想法，拆成幾個更接近真實場景的方向。</p><h3 id="_12-2-讓-ai-幫你整理訪談原話" tabindex="-1">12.2 讓 AI 幫你整理訪談原話 <a class="header-anchor" href="#_12-2-讓-ai-幫你整理訪談原話" aria-label="Permalink to “12.2 讓 AI 幫你整理訪談原話”">​</a></h3><p>如果你已經做了幾次使用者訪談，可以把訪談記錄交給 AI，讓它幫你提煉反覆出現的場景、觸發點、替代方案和成功標準。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是 5 位使用者的訪談原話。</span></span>
<span class="line"><span>請不要先給解決方案，而是按 JTBD 框架整理：</span></span>
<span class="line"><span>1. 使用者處在什麼場景</span></span>
<span class="line"><span>2. 觸發他採取行動的事件是什麼</span></span>
<span class="line"><span>3. 他真正想完成的進展是什麼</span></span>
<span class="line"><span>4. 當前替代方案是什麼</span></span>
<span class="line"><span>5. 他最在意的成功標準是什麼</span></span>
<span class="line"><span>6. 哪些資訊在多位使用者中重複出現</span></span>
<span class="line"><span>最後整理成 3 條最值得優先驗證的 JTBD 假設。</span></span></code></pre></div><p>一個很簡單的小白輸入也可以這樣寫：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我問了 3 個人，他們大概是這樣說的：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 每次要投實習我都得重新改簡歷，特別煩。</span></span>
<span class="line"><span>2. 我其實最怕的是不知道自己寫得對不對。</span></span>
<span class="line"><span>3. 我現在會先找學長學姐幫我看，但每次都不好意思總麻煩別人。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你幫我整理一下，他們真正想完成的事情是什麼。</span></span></code></pre></div><p>AI 可能輸出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>整理結果：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 共同場景：準備投遞實習前，需要處理簡歷</span></span>
<span class="line"><span>- 共同困難：不知道如何修改到“夠好”</span></span>
<span class="line"><span>- 當前替代方案：找學長學姐幫看，自己反覆修改</span></span>
<span class="line"><span>- 可能的 JTBD：</span></span>
<span class="line"><span>  當我準備投遞實習時，我想更快判斷簡歷是否已經達到可投遞水平，</span></span>
<span class="line"><span>  以便我不要一直卡在“再改一改”而遲遲投不出去。</span></span></code></pre></div><p>這種輸出很有用，因為它幫你從零散原話裡提煉出更像“需求”的東西。</p><h3 id="_12-3-讓-ai-幫你做一輪輕量級網路調研" tabindex="-1">12.3 讓 AI 幫你做一輪輕量級網路調研 <a class="header-anchor" href="#_12-3-讓-ai-幫你做一輪輕量級網路調研" aria-label="Permalink to “12.3 讓 AI 幫你做一輪輕量級網路調研”">​</a></h3><p>在你還沒開始大規模訪談前，可以先讓 AI 幫你做一些很輕的外部資訊掃描，比如：</p><ul><li>公開論壇或社羣裡，大家是怎麼抱怨這個問題的</li><li>市面上已有產品主要在解決哪一層問題</li><li>使用者最常見的替代方案是什麼</li><li>常見評價裡，大家最滿意和最不滿意的點是什麼</li></ul><p>這種調研不能代替真實使用者訪談，但很適合作為 Discover 階段的熱身，幫你先建立問題地圖。</p><p>一個簡單輸入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請你幫我查一查：</span></span>
<span class="line"><span>“大學生改簡歷、投實習時最常見的痛點是什麼？”</span></span>
<span class="line"><span>優先看公開論壇、經驗帖、求職社羣裡大家自己說的話。</span></span>
<span class="line"><span>幫我整理成 5 條最常見問題。</span></span></code></pre></div><p>AI 可能輸出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>常見痛點整理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 不知道簡歷該寫什麼，經歷太少</span></span>
<span class="line"><span>2. 不知道怎麼針對不同崗位修改</span></span>
<span class="line"><span>3. 改了很多版，但始終不確定是否夠好</span></span>
<span class="line"><span>4. 找不到可靠的人幫忙看</span></span>
<span class="line"><span>5. 投遞流程複雜，容易拖延</span></span></code></pre></div><p>這類輸出不能當最終結論，但很適合幫你先決定要優先訪談哪類問題。</p><h3 id="_12-4-讓-ai-充當-反方" tabindex="-1">12.4 讓 AI 充當“反方” <a class="header-anchor" href="#_12-4-讓-ai-充當-反方" aria-label="Permalink to “12.4 讓 AI 充當“反方””">​</a></h3><p>很多時候，我們會對自己的想法太有感情。你可以專門讓 AI 扮演一個挑刺的人，逼你把問題說得更清楚：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請你扮演一個非常嚴格的產品研究顧問。</span></span>
<span class="line"><span>下面是我的 JTBD 假設：[你的假設]</span></span>
<span class="line"><span>請從以下角度批判它：</span></span>
<span class="line"><span>1. 這個場景是否過寬</span></span>
<span class="line"><span>2. 這個 job 是否寫成了功能而不是真正進展</span></span>
<span class="line"><span>3. 替代方案是否太弱</span></span>
<span class="line"><span>4. 成功標準是否不夠清楚</span></span>
<span class="line"><span>5. 這個假設最需要被驗證的風險是什麼</span></span></code></pre></div><p>這樣做的好處是，你能更快發現自己是在看需求，還是只是在看自己喜歡的方案。</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>請你根據上文內容，完成下列作業：</p><ol><li>選一個你最近想做的產品點子，用一句 JTBD 公式把它寫清楚</li><li>為這個點子補齊 5 個要素：場景、觸發、進展、替代方案、成功標準</li><li>找 3 個潛在使用者，至少問出一次“最近一次你遇到這個問題是什麼時候”</li><li>把訪談原話交給 AI，整理成 3 條最值得優先驗證的 JTBD 假設</li></ol><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to “延伸閱讀”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{k as __pageData,_ as default};
